func (v tickPrev) hashWire(h *zigui.WireHasher) {
	h.Str(1, v.ID)
	h.Uint(2, uint64(v.Hash))
}

func (v tickPrev) wireEq(o *tickPrev) bool {
	if v.ID != o.ID {
		return false
	}
	if v.Hash != o.Hash {
		return false
	}
	return true
}

func (v tickPrev) deltaWire(w *zigui.WireWriter, prev *tickPrev) {
	if v.ID != prev.ID {
		if v.ID == "" {
			w.Clear(1)
		} else {
			w.Str(1, v.ID)
		}
	}
	if v.Hash != prev.Hash {
		if v.Hash == 0 {
			w.Clear(2)
		} else {
			w.Uint(2, uint64(v.Hash))
		}
	}
}

